import Foundation

enum DirectoryType {
    case documents
    case caches
    case temporary
}

func isBackedUpToiCloud(dir: DirectoryType) -> Bool {
    switch dir {
    case .documents:
        return true
    case .caches, .temporary:
        return false
    }
}
print("Documents backed up: \(isBackedUpToiCloud(dir: .documents))")

