import Foundation

enum WriteOption {
    case standard
    case atomic
}
func writeMode(option: WriteOption) -> String {
    switch option {
    case .atomic:
        return "auxiliary file rename"
    case .standard:
        return "direct write"
    }
}
print("Write mode: \(writeMode(option: .atomic))")

