struct StorageAdvisor {
    static func recommendStorage(isSecret: Bool, byteSize: Int) -> String {
        if isSecret {
            return "keychain"
        } else if byteSize > 102400 {
            return "fileManager"
        } else {
            return "userDefaults"
        }
    }
}

let secretRes = StorageAdvisor.recommendStorage(isSecret: true, byteSize: 50)
let fileRes = StorageAdvisor.recommendStorage(isSecret: false, byteSize: 500000)
let prefRes = StorageAdvisor.recommendStorage(isSecret: false, byteSize: 100)
print("Advice: \(secretRes), \(fileRes), \(prefRes)")

struct DirectoryRouter {
    func directoryURL(isUserCreated: Bool, isCache: Bool) -> String {
        if isUserCreated {
            return "Documents"
        } else if isCache {
            return "Library/Caches"
        } else {
            return "Library/Application Support"
        }
    }
}

let router = DirectoryRouter()
let d1 = router.directoryURL(isUserCreated: true, isCache: false)
let d2 = router.directoryURL(isUserCreated: false, isCache: true)
let d3 = router.directoryURL(isUserCreated: false, isCache: false)
print("Dirs: \(d1), \(d2), \(d3)")

class PreferencesValidator {
    func isValidKey(_ key: String) -> Bool {
        return !key.isEmpty && key.count < 100
    }
}

let val = PreferencesValidator()
let validCheck = val.isValidKey("hasSeenWalkthrough")
let emptyCheck = val.isValidKey("")
print("Keys valid: \(validCheck && !emptyCheck)")
